# Illustrative pattern, not the CARE-SD code
def label_interview(chunks, slm):
    verdicts = []
    for chunk in chunks:
        ctx = adapt_context(chunk)                 # sector, speaker, topic
        draft = slm.classify_hierarchically(ctx)   # broad category, then narrow
        if not explanation_supports(draft, chunk):
            draft = slm.retry(ctx, feedback=draft.explanation)
        verdicts.append(draft)
    return reconcile_across_batches(verdicts)      # one statement, one verdict
